// Tiene solo i video non ancora caricati (la memoria resta fra un'esecuzione e l'altra
// solo quando il flusso è ATTIVO: le prove a mano con «Esegui» non se lo ricordano).
const memoria = $getWorkflowStaticData('global');
memoria.fatti = memoria.fatti || [];
// 25/10/2026: il flusso gira ogni mezz'ora. Tetto: 6 caricamenti per giorno di quota YouTube (quota gratis 10.000 unità,
// un caricamento ne costa 1.600; si azzera a mezzanotte del Pacifico). Il canale ne ha accettati 10 in 24 ore, quindi 6 sta dentro.
const TETTO = 6;
const giorno = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Los_Angeles' });
if (memoria.giorno !== giorno) { memoria.giorno = giorno; memoria.oggi = 0; }
const posto = Math.max(0, TETTO - (memoria.oggi || 0));
const pronti = [];
for (const it of $('Leggi i video pronti su GitHub').all()) {
  const r = it.json;
  if (!String(r.tag_name || '').startsWith('video-') || memoria.fatti.includes(r.tag_name)) continue;
  // solo in inglese (Marco, 22/10/2026) e solo i video nati dopo quelli pubblicati a mano fino al 25/10/2026
  if (r.tag_name.endsWith('-it') || String(r.created_at) < '2026-10-25T00:00:00Z') continue;
  const mp4 = (r.assets || []).find((a) => a.name.endsWith('.mp4'));
  const info = (r.assets || []).find((a) => a.name.endsWith('.json'));
  if (mp4 && info) pronti.push({ json: { tag: r.tag_name, mp4: mp4.browser_download_url, info: info.browser_download_url, creato: r.created_at } });
}
// i più vecchi prima, fino al tetto del giorno
return pronti.sort((a, b) => a.json.creato.localeCompare(b.json.creato)).slice(0, posto);

// Segna il video come caricato, così non si ricarica; conta i caricamenti del giorno per il tetto
const memoria = $getWorkflowStaticData('global');
const tag = $('Solo i video nuovi').item.json.tag;
memoria.fatti = [...(memoria.fatti || []), tag].slice(-300);
memoria.oggi = (memoria.oggi || 0) + 1;
return { json: { caricato: tag, youtube: $json.id ? `https://youtube.com/shorts/${$json.id}` : null } };

// 23/10/2026: n8n aveva caricato 6 video sul canale personale «Marco D'Elia», perché il collegamento
// Google era stato fatto prima che esistesse FreeLLMArena. YouTube carica sempre sul canale del collegamento:
// se non è FreeLLMArena il flusso si ferma con un errore e non carica niente.
const GIUSTO = 'UCaDO6FcvstiPM83lh5eH7_w';
const canale = ($input.first().json.items || [])[0] || {};
if (canale.id !== GIUSTO) throw new Error(`Canale sbagliato: il collegamento YouTube è su «${canale.snippet?.title || canale.id || 'nessun canale'}», non su FreeLLMArena. Ricollega la credenziale scegliendo FreeLLMArena.`);
return [{ json: { canale: canale.snippet.title } }];
